package com.crm.hr.service;
import com.crm.hr.repository.HrStatisticsRepository;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true) public class HrStatisticsService {
 public record Summary(LocalDate from,LocalDate to,String policy,Map<String,Long> leaves,long approvedEmployeeDays,Map<String,Long> trainings,Map<String,Long> evaluations,Map<String,Long> offers,Map<String,Long> applications){}
 private final HrStatisticsRepository repository;public HrStatisticsService(HrStatisticsRepository r){repository=r;}
 public Summary read(LocalDate from,LocalDate to){HrAuthorization.requireAdmin();HrPeriod.require(from,to);return new Summary(from,to,"CURRENT_STATUS_OVERLAPPING_CIVIL_DATES;RECRUITMENT_CREATED_IN_PERIOD",counts(repository.leaves(from,to),List.of("PENDING","APPROVED","REJECTED")),repository.approvedEmployeeDays(from,to),counts(repository.trainings(from,to),List.of("PLANNED","IN_PROGRESS","COMPLETED","CANCELLED")),counts(repository.evaluations(from,to),List.of("DRAFT","FINALIZED")),counts(repository.offers(from.atStartOfDay(),to.plusDays(1).atStartOfDay()),List.of("OPEN","CLOSED")),counts(repository.applications(from.atStartOfDay(),to.plusDays(1).atStartOfDay()),List.of("RECEIVED","IN_REVIEW","ACCEPTED","REJECTED")));}
 private Map<String,Long> counts(List<HrStatisticsRepository.StatusCount> rows,List<String> allowed){Map<String,Long> result=new LinkedHashMap<>();allowed.forEach(s->result.put(s,0L));for(var row:rows){if(!result.containsKey(row.getStatus())||row.getTotal()<0)throw new IllegalStateException("Invalid HR aggregate");result.put(row.getStatus(),row.getTotal());}return Collections.unmodifiableMap(result);}
}